assetId = self.view.custom.assets.selectedAssetInfo.assetId
parentId = self.view.custom.assets.selectedAssetInfo.parentId
if assetId is None: return
parentPath = system.kanoa.utilities.getFieldValue('assetPath', system.kanoa.asset.getAssets({'assetId': self.view.custom.assets.selectedAssetInfo.parentId}))

system.perspective.print("duplicateAsset() called for %s"%assetId)
self.view.custom.info = {"showBar": True, "text": "Creating assets", "type": "INFO"}

retVal, msg = system.kanoa.asset.copyAsset(assetId, self.view.custom.security.userId)
self.updateSortOrder(parentId)

if msg: system.perspective.sendMessage('showWarningToast', {'message': 'Unable to copy asset. %s'%msg})
else: system.perspective.sendMessage('showSuccessfulToast', {'message': 'Asset copied'})	

self.view.custom.info = {"showBar": False, "text": "", "type": "INFO"}

self.view.refreshBinding("custom.assets.data")

return

system.perspective.print("saveAssetAttributes() called")	
attrList = self.view.custom.customAttributes.list or []
userId = self.view.custom.security.userId
actionCount = 0

for attr in attrList:
	if attr.state == 'drop': continue
	if attr.state == 'delete': 
		system.kanoa.asset.deleteAssetAttribute(attr['attrId'], userId)
		actionCount += 1
		system.perspective.sendMessage('showSuccessfulToast', {'message': "Attribute %s deleted"%attr['label']})			

	elif attr.state in ('insert', 'update'):
		system.perspective.print("calling addAssetAttribute() with %s %s %s %s"%(assetId, attr['label'], attr['text'], userId))
		assetAttributeId, msg = system.kanoa.asset.addAssetAttribute(assetId, attr['label'], attr['text'], userId)
		actionCount += 1

		if msg: system.perspective.sendMessage('showSuccessfulToast', {'message': "Attribute saved"})
		else: system.perspective.sendMessage('showFailerToast', {'message': "Attribute couldn't be saved - %s"%msg})

assetType = system.kanoa.asset.getAssetTypes({'assetTypeId': self.view.custom.assets.selectedAssetInfo.assetTypeId})
if assetType.getRowCount() and assetType[0]['assetTypeName'] in ('site', 'area', 'line'):
	for attrItem in self.view.custom.assetInfo:
		if attrItem in ['oeeThresholds', 'productionDay', 'mainDisplay']: continue
		if not self.view.custom.assetInfo[attrItem]['inherited']:
			attrItemName = '_' + attrItem
			assetAttributes = [item['label'] for item in self.view.custom.customAttributes.list]
			assetAttributeId, msg = system.kanoa.asset.addAssetAttribute(assetId, attrItemName, self.view.custom.assetInfo[attrItem]['value'], userId)
			actionCount += 1

if actionCount == 0: system.perspective.sendMessage('showInfoToast', {'message': "No attribute changes needed to be saved"})
return


